const props=defineProps<{user?:AuthUser|null}>(),emit=defineEmits<{logout:[];'refresh-user':[]}>(),route=useRoute(),open=ref(false),userMenu=ref(false),quickMenu=ref(false),epsModal=ref(false),selectedCompany=ref(0),changing=ref(false),companyError=ref('');const activeModule=computed(()=>getModule(route.path.split('/')[2]??'')),userName=computed(()=>props.user?.name??props.user?.nombre??props.user?.username??'Usuario'),initials=computed(()=>userName.value.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()),companies=computed(()=>props.user?.empresas??[]),activeCompany=computed(()=>props.user?.empresa?.nombre_comercial??props.user?.empresa?.nombre_formal??props.user?.empresa?.nombre??''),companyLogo=computed(()=>props.user?.empresa?.imagen?`/img/logos/app/${encodeURIComponent(props.user.empresa.imagen)}`:'');function closeMenus(){userMenu.value=false;quickMenu.value=false}function showCompanies(){selectedCompany.value=props.user?.empresa_id??props.user?.empresa?.id??0;companyError.value='';closeMenus();epsModal.value=true}async function changeCompany(){if(!selectedCompany.value)return;changing.value=true;companyError.value='';try{await authService.cambiarEmpresa(selectedCompany.value);emit('refresh-user');epsModal.value=false;window.location.assign('/inicio')}catch(e){companyError.value=e instanceof Error?e.message:'No se pudo cambiar la EPS.'}finally{changing.value=false}}function logout(){closeMenus();emit('logout')}
</script>
