or="company in companies" :key="company.id" :value="company.id">{{company.nombre_formal||company.nombre}}</option></select></label><p v-if="!companies.length" class="no-companies">No existen otras empresas asignadas a este usuario.</p><footer><button type="button" class="cancel" @click="epsModal=false">Cancelar</button><button :disabled="changing||!selectedCompany||!companies.length">{{changing?'Cambiando…':'Cambiar EPS'}}</button></footer></form></div></div></template>
